        }

        return Math.abs(hash) % this.size;
    }

    add(item) {
        for (let i = 0; i < this.numHashes; i++) {
            const index = this._hash(item, i);
            this.bitArray[index] = true;
        }
    }

    contains(item) {
        for (let i = 0; i < this.numHashes; i++) {
            const index = this._hash(item, i);
            if (!this.bitArray[index]) {
                return false; // Definitely not in set
            }
        }
        return true; // Probably in set
    }

    // Calculate optimal number of hash functions
    static optimalHashes(expectedItems, size) {
        return Math.ceil((size / expectedItems) * Math.log(2));
    }

    // Calculate optimal bit array size
    static optimalSize(expectedItems, falsePositiveRate) {
        return Math.ceil(
            -(expectedItems * Math.log(falsePositiveRate)) / (Math.log(2) ** 2)
        );
    }

    getFalsePositiveRate(numItems) {
        const k = this.numHashes;
        const m = this.size;
        const n = numItems;
        return Math.pow(1 - Math.exp(-k * n / m), k);
    }
}

