template<typename T>
class Deque {
private:
    struct Node {
        T data;
        Node* prev;
        Node* next;
        Node(T data) : data(data), prev(nullptr), next(nullptr) {}
    };

    Node* front;
    Node* rear;
    int count;

public:
    Deque() : front(nullptr), rear(nullptr), count(0) {}

    ~Deque() {
        while (!isEmpty()) {
            removeFront();
        }
    }

    void addFront(T data) {
        Node* newNode = new Node(data);

        if (isEmpty()) {
            front = rear = newNode;
        } else {
            newNode->next = front;
            front->prev = newNode;
            front = newNode;
        }
        count++;
    }

    void addRear(T data) {
        Node* newNode = new Node(data);

        if (isEmpty()) {
            front = rear = newNode;
        } else {
            newNode->prev = rear;
            rear->next = newNode;
            rear = newNode;
        }
        count++;
    }

    T removeFront() {
        if (isEmpty()) {
            throw runtime_error("Deque is empty");
        }

        Node* temp = front;
        T data = temp->data;
        front = front->next;

        if (front) {
            front->prev = nullptr;
        } else {
            rear = nullptr;
        }

        delete temp;
        count--;
        return data;
    }

    T removeRear() {
        if (isEmpty()) {
            throw runtime_error("Deque is empty");
        }

        Node* temp = rear;
        T data = temp->data;
        rear = rear->prev;

        if (rear) {
            rear->next = nullptr;
        } else {
            front = nullptr;
        }

        delete temp;
        count--;
        return data;
    }

    T peekFront() const {
        if (isEmpty()) throw runtime_error("Deque is empty");
        return front->data;
    }

    T peekRear() const {
        if (isEmpty()) throw runtime_error("Deque is empty");
        return rear->data;
    }

    bool isEmpty() const { return count == 0; }
    int size() const { return count; }
};

