public class PriorityQueueCustom<T extends Comparable<T>> {
    private List<T> heap;
    private Comparator<T> comparator;

    public PriorityQueueCustom() {
        this(null);
    }

    public PriorityQueueCustom(Comparator<T> comparator) {
        this.heap = new ArrayList<>();
        this.comparator = comparator;
    }

    private int parent(int i) { return (i - 1) / 2; }
    private int leftChild(int i) { return 2 * i + 1; }
    private int rightChild(int i) { return 2 * i + 2; }

    private boolean compare(T a, T b) {
        if (comparator != null) {
            return comparator.compare(a, b) < 0;
        }
        return a.compareTo(b) < 0;
    }

    private void swap(int i, int j) {
        T temp = heap.get(i);
        heap.set(i, heap.get(j));
        heap.set(j, temp);
    }

    public void offer(T element) {
        heap.add(element);
        heapifyUp(heap.size() - 1);
    }

    private void heapifyUp(int index) {
        while (index > 0 && compare(heap.get(index), heap.get(parent(index)))) {
            swap(index, parent(index));
            index = parent(index);
        }
    }

    public T poll() {
        if (isEmpty()) {
            throw new NoSuchElementException("Priority queue is empty");
        }

        T result = heap.get(0);
        heap.set(0, heap.get(heap.size() - 1));
        heap.remove(heap.size() - 1);

        if (!isEmpty()) {
            heapifyDown(0);
        }

        return result;
    }

    private void heapifyDown(int index) {
        int smallest = index;
        int left = leftChild(index);
        int right = rightChild(index);

        if (left < heap.size() && compare(heap.get(left), heap.get(smallest))) {
            smallest = left;
        }

        if (right < heap.size() && compare(heap.get(right), heap.get(smallest))) {
            smallest = right;
        }

        if (smallest != index) {
            swap(index, smallest);
            heapifyDown(smallest);
        }
    }

    public T peek() {
        if (isEmpty()) {
            throw new NoSuchElementException("Priority queue is empty");
        }
        return heap.get(0);
    }

    public boolean isEmpty() { return heap.isEmpty(); }
    public int size() { return heap.size(); }
}

class BTree:
    """B-Tree implementation for disk-based storage"""

    class Node:
        def __init__(self, leaf=True):
            self.keys = []
            self.children = []
            self.leaf = leaf

    def __init__(self, t):
        """t is minimum degree (minimum number of keys is t-1)"""
        self.root = self.Node()
        self.t = t

    def search(self, k, node=None):
        if node is None:
            node = self.root

        i = 0
        while i < len(node.keys) and k > node.keys[i]:
            i += 1

        if i < len(node.keys) and k == node.keys[i]:
            return (node, i)
        elif node.leaf:
            return None
        else:
            return self.search(k, node.children[i])

    def insert(self, k):
        root = self.root
        if len(root.keys) == (2 * self.t) - 1:
            new_root = self.Node(leaf=False)
            new_root.children.append(self.root)
            self._split_child(new_root, 0)
            self.root = new_root
        self._insert_non_full(self.root, k)

    def _insert_non_full(self, node, k):
        i = len(node.keys) - 1

        if node.leaf:
            node.keys.append(None)
            while i >= 0 and k < node.keys[i]:
                node.keys[i + 1] = node.keys[i]
                i -= 1
            node.keys[i + 1] = k
        else:
            while i >= 0 and k < node.keys[i]:
                i -= 1
            i += 1

            if len(node.children[i].keys) == (2 * self.t) - 1:
                self._split_child(node, i)
                if k > node.keys[i]:
                    i += 1

            self._insert_non_full(node.children[i], k)

    def _split_child(self, parent, i):
        t = self.t
        full_child = parent.children[i]
        new_child = self.Node(leaf=full_child.leaf)

        mid_key = full_child.keys[t - 1]
        new_child.keys = full_child.keys[t:]
        full_child.keys = full_child.keys[:t - 1]

        if not full_child.leaf:
            new_child.children = full_child.children[t:]
            full_child.children = full_child.children[:t]

        parent.keys.insert(i, mid_key)
        parent.children.insert(i + 1, new_child)

class SuffixTree {
    constructor() {
        this.root = { children: {}, suffixLink: null };
    }

    build(text) {
        text += '$'; // Terminal character
        const n = text.length;

        for (let i = 0; i < n; i++) {
            this._addSuffix(text, i);
        }
    }

    _addSuffix(text, pos) {
        let node = this.root;

        for (let i = pos; i < text.length; i++) {
            const char = text[i];

            if (!node.children[char]) {
                node.children[char] = {
                    children: {},
                    suffixLink: null,
                    start: i,
                    end: text.length - 1,
                    suffixIndex: pos
                };
            }

            node = node.children[char];
        }
    }

    search(pattern) {
        let node = this.root;

        for (const char of pattern) {
            if (!node.children[char]) {
                return false;
            }
            node = node.children[char];
        }

        return true;
    }

    findAllOccurrences(pattern) {
        let node = this.root;

        for (const char of pattern) {
            if (!node.children[char]) {
                return [];
            }
            node = node.children[char];
        }

        const occurrences = [];
        this._collectSuffixIndices(node, occurrences);
        return occurrences;
    }

    _collectSuffixIndices(node, result) {
        if (node.suffixIndex !== undefined) {
            result.push(node.suffixIndex);
        }

        for (const child of Object.values(node.children)) {
            this._collectSuffixIndices(child, result);
        }
    }
}

