template<typename T>
class FibonacciHeap {
private:
    struct Node {
        T key;
        int degree;
        bool marked;
        Node* parent;
        Node* child;
        Node* left;
        Node* right;

        Node(T k) : key(k), degree(0), marked(false), 
                    parent(nullptr), child(nullptr), left(this), right(this) {}
    };

    Node* minNode;
    int nodeCount;
    function<bool(T, T)> compare;

    void consolidate() {
        int maxDegree = static_cast<int>(log2(nodeCount)) + 1;
        vector<Node*> degreeTable(maxDegree, nullptr);

        vector<Node*> rootList;
        Node* current = minNode;
        if (current) {
            do {
                rootList.push_back(current);
                current = current->right;
            } while (current != minNode);
        }

        for (Node* node : rootList) {
            int degree = node->degree;
            while (degreeTable[degree] != nullptr) {
                Node* other = degreeTable[degree];
                if (compare(other->key, node->key)) {
                    swap(node, other);
                }
                link(other, node);
                degreeTable[degree] = nullptr;
                degree++;
            }
            degreeTable[degree] = node;
        }

        minNode = nullptr;
        for (Node* node : degreeTable) {
            if (node) {
                if (!minNode || compare(node->key, minNode->key)) {
                    minNode = node;
                }
            }
        }
    }

    void link(Node* child, Node* parent) {
        // Remove child from root list
        child->left->right = child->right;
        child->right->left = child->left;

        // Add child to parent's child list
        if (!parent->child) {
            parent->child = child;
            child->left = child->right = child;
        } else {
            child->left = parent->child;
            child->right = parent->child->right;
            parent->child->right->left = child;
            parent->child->right = child;
        }

        child->parent = parent;
        parent->degree++;
        child->marked = false;
    }

public:
    FibonacciHeap(function<bool(T, T)> cmp = less<T>()) 
        : minNode(nullptr), nodeCount(0), compare(cmp) {}

    void insert(T key) {
        Node* newNode = new Node(key);

        if (!minNode) {
            minNode = newNode;
        } else {
            newNode->left = minNode;
            newNode->right = minNode->right;
            minNode->right->left = newNode;
            minNode->right = newNode;

            if (compare(key, minNode->key)) {
                minNode = newNode;
            }
        }
        nodeCount++;
    }

    T extractMin() {
        if (!minNode) throw runtime_error("Heap is empty");

        Node* z = minNode;
        T minKey = z->key;

        if (z->child) {
            Node* child = z->child;
            do {
                Node* next = child->right;
                child->parent = nullptr;
                child = next;
            } while (child != z->child);
        }

        z->left->right = z->right;
        z->right->left = z->left;

        if (z == z->right) {
            minNode = nullptr;
        } else {
            minNode = z->right;
            consolidate();
        }

        nodeCount--;
        delete z;
        return minKey;
    }

    T getMin() const {
        if (!minNode) throw runtime_error("Heap is empty");
        return minNode->key;
    }

    bool isEmpty() const { return minNode == nullptr; }
    int size() const { return nodeCount; }
};

public class BinomialHeap {
    private class Node {
        int key;
        int degree;
        Node parent;
        Node child;
        Node sibling;

        Node(int key) {
            this.key = key;
            this.degree = 0;
        }
    }

    private Node head;

    public BinomialHeap() {
        head = null;
    }

    public void insert(int key) {
        BinomialHeap temp = new BinomialHeap();
        temp.head = new Node(key);
        head = union(this, temp).head;
    }

    public int getMin() {
        if (head == null) {
            throw new RuntimeException("Heap is empty");
        }

        Node minNode = head;
        Node current = head.sibling;

        while (current != null) {
            if (current.key < minNode.key) {
                minNode = current;
            }
            current = current.sibling;
        }

        return minNode.key;
    }

    public int extractMin() {
        if (head == null) {
            throw new RuntimeException("Heap is empty");
        }

        // Find minimum
        Node minNode = head;
        Node minPrev = null;
        Node current = head.sibling;
        Node prev = head;

        while (current != null) {
            if (current.key < minNode.key) {
                minNode = current;
                minPrev = prev;
            }
            prev = current;
            current = current.sibling;
        }

        // Remove min from root list
        if (minPrev == null) {
            head = minNode.sibling;
        } else {
            minPrev.sibling = minNode.sibling;
        }

        // Reverse children list
        Node child = minNode.child;
        Node newHead = null;

        while (child != null) {
            Node next = child.sibling;
            child.sibling = newHead;
            child.parent = null;
            newHead = child;
            child = next;
        }

        // Union with children
        BinomialHeap temp = new BinomialHeap();
        temp.head = newHead;
        head = union(this, temp).head;

        return minNode.key;
    }

    private BinomialHeap union(BinomialHeap h1, BinomialHeap h2) {
        BinomialHeap result = new BinomialHeap();
        result.head = merge(h1.head, h2.head);

        if (result.head == null) return result;

        Node prev = null;
        Node current = result.head;
        Node next = current.sibling;

        while (next != null) {
            if (current.degree != next.degree || 
                (next.sibling != null && next.sibling.degree == current.degree)) {
                prev = current;
                current = next;
            } else if (current.key <= next.key) {
                current.sibling = next.sibling;
                link(next, current);
            } else {
                if (prev == null) {
                    result.head = next;
                } else {
                    prev.sibling = next;
                }
                link(current, next);
                current = next;
            }
            next = current.sibling;
        }

        return result;
    }

    private Node merge(Node h1, Node h2) {
        if (h1 == null) return h2;
        if (h2 == null) return h1;

        Node head;
        if (h1.degree <= h2.degree) {
            head = h1;
            h1 = h1.sibling;
        } else {
            head = h2;
            h2 = h2.sibling;
        }

        Node current = head;
        while (h1 != null && h2 != null) {
            if (h1.degree <= h2.degree) {
                current.sibling = h1;
                h1 = h1.sibling;
            } else {
                current.sibling = h2;
                h2 = h2.sibling;
            }
            current = current.sibling;
        }

        current.sibling = (h1 != null) ? h1 : h2;
        return head;
    }

    private void link(Node child, Node parent) {
        child.parent = parent;
        child.sibling = parent.child;
        parent.child = child;
        parent.degree++;
    }
}

class IntervalTree {
    constructor() {
        this.root = null;
    }

    insert(low, high) {
        this.root = this._insertNode(this.root, low, high);
    }

    _insertNode(node, low, high) {
        if (!node) {
            return {
                low,
                high,
                max: high,
                left: null,
                right: null
            };
        }

        if (low < node.low) {
            node.left = this._insertNode(node.left, low, high);
        } else {
            node.right = this._insertNode(node.right, low, high);
        }

        // Update max
        node.max = Math.max(node.max, high);
        if (node.left) node.max = Math.max(node.max, node.left.max);
        if (node.right) node.max = Math.max(node.max, node.right.max);

        return node;
    }

    overlaps(low, high) {
        return this._searchOverlap(this.root, low, high);
    }

    _searchOverlap(node, low, high) {
        if (!node) return null;

        // Check if current interval overlaps
        if (this._doOverlap(node.low, node.high, low, high)) {
            return { low: node.low, high: node.high };
        }

        // If left subtree exists and max >= low, search left
        if (node.left && node.left.max >= low) {
            return this._searchOverlap(node.left, low, high);
        }

        // Otherwise search right
        return this._searchOverlap(node.right, low, high);
    }

    getAllOverlaps(low, high) {
        const result = [];
        this._getAllOverlaps(this.root, low, high, result);
        return result;
    }

    _getAllOverlaps(node, low, high, result) {
        if (!node) return;

        if (this._doOverlap(node.low, node.high, low, high)) {
            result.push({ low: node.low, high: node.high });
        }

        if (node.left && node.left.max >= low) {
            this._getAllOverlaps(node.left, low, high, result);
        }

        this._getAllOverlaps(node.right, low, high, result);
    }

    _doOverlap(l1, h1, l2, h2) {
        return l1 <= h2 && l2 <= h1;
    }
}

